import json
import os
import sys
import urllib.request
import urllib.error
import urllib.parse
from pathlib import Path

def sanitize_filename(url):
    sanitized = []
    for c in url:
        if c.isalnum() or c in {'-', '.', '_'}:
            sanitized.append(c)
        else:
            sanitized.append('_')
    return ''.join(sanitized)

def fetch_url(url):
    try:
        with urllib.request.urlopen(url) as response:
            return response.read().decode('utf-8')
    except Exception as e:
        print(f"Error fetching URL: {e}", file=sys.stderr)
        sys.exit(1)

def get_cached_file(url):
    cache_dir = Path('./pack_cache')
    cache_dir.mkdir(exist_ok=True)
    sanitized = sanitize_filename(url)
    cache_path = cache_dir / f"{sanitized}.json"
    if cache_path.exists():
        try:
            with open(cache_path, 'r', encoding='utf-8') as f:
                return f.read()
        except Exception as e:
            print(f"Error reading cache file: {e}", file=sys.stderr)
            sys.exit(1)
    return None

def save_to_cache(url, data):
    cache_dir = Path('./pack_cache')
    cache_dir.mkdir(exist_ok=True)
    sanitized = sanitize_filename(url)
    cache_path = cache_dir / f"{sanitized}.json"
    with open(cache_path, 'w', encoding='utf-8') as f:
        f.write(data)

def evaluate_expression(expr, vars_dict):
    try:
        # Replace variables with their values
        for var, value in vars_dict.items():
            expr = expr.replace(var, str(value))
        # Evaluate the arithmetic expression
        return eval(expr, {'__builtins__': None}, {})
    except Exception as e:
        print(f"Error evaluating expression '{expr}': {e}", file=sys.stderr)
        sys.exit(1)

def process_pack(pack_source, output_path):
    try:
        if pack_source.startswith(('http://', 'https://')):
            data = fetch_url(pack_source)
            save_to_cache(pack_source, data)
        else:
            with open(pack_source, 'r', encoding='utf-8') as f:
                data = f.read()

        pack = json.loads(data)
        vars_dict = pack['vars']
        output_names = pack['output']

        # Evaluate each expression in vars_dict
        evaluated_vars = {}
        for name, expr in vars_dict.items():
            evaluated_vars[name] = evaluate_expression(expr, evaluated_vars)

        # Prepare the output JSON
        output_json = {name: evaluated_vars[name] for name in output_names}

        # Write the output JSON
        with open(output_path, 'w', encoding='utf-8') as f:
            json.dump(output_json, f, indent=2, ensure_ascii=False)

    except json.JSONDecodeError:
        print(f"Error parsing JSON: {pack_source}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python runpack.py <pack_source> <output_path>", file=sys.stderr)
        sys.exit(1)

    pack_source = sys.argv[1]
    output_path = sys.argv[2]
    process_pack(pack_source, output_path)

import argparse
import json
import os
import requests
from pathlib import Path

def fetch_url(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except Exception as e:
        print(f"Error fetching URL: {e}", file=sys.stderr)
        sys.exit(1)

def cache_filename(url):
    safe = []
    for c in url:
        if c.isalnum() or c in {'-', '.'}:
            safe.append(c)
        else:
            safe.append('_')
    return f"pack_cache/{''.join(safe)}.json"

def load_pack(source):
    if source.startswith(('http://', 'https://')):
        text = fetch_url(source)
        cache_path = Path(cache_filename(source))
        if cache_path.exists():
            with open(cache_path, 'r') as f:
                return json.load(f)
        with open(cache_path, 'w') as f:
            json.dump(json.loads(text), f, indent=2)
        return json.loads(text)
    else:
        try:
            with open(source, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Error reading file: {e}", file=sys.stderr)
            sys.exit(1)

def evaluate_expression(expr, vars_dict):
    try:
        return eval(expr, {'__builtins__': None}, vars_dict)
    except Exception as e:
        print(f"Error evaluating expression '{expr}': {e}", file=sys.stderr)
        sys.exit(1)

def process_pack(pack):
    vars_dict = pack['vars']
    output_names = pack['output']
    results = {}

    for name in output_names:
        expr = vars_dict[name]
        if name in vars_dict:
            # Handle circular references by evaluating in a loop
            evaluated = None
            while True:
                try:
                    evaluated = evaluate_expression(expr, vars_dict)
                    break
                except Exception as e:
                    print(f"Error in circular reference for '{name}': {e}", file=sys.stderr)
                    sys.exit(1)
            results[name] = evaluated
        else:
            results[name] = evaluate_expression(expr, vars_dict)

    return results

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('pack_source', help='Source pack (file or URL)')
    parser.add_argument('output_path', help='Output JSON file path')
    args = parser.parse_args()

    if not os.path.exists('./pack_cache'):
        os.makedirs('./pack_cache')

    pack = load_pack(args.pack_source)
    results = process_pack(pack)

    with open(args.output_path, 'w') as f:
        json.dump(results, f, indent=2)

    print()  # Ensure trailing newline

if __name__ == "__main__":
    import sys
    main()

import os
import sys
import json
import requests
from urllib.parse import urlparse
from pathlib import Path

def cache_filename(url):
    parsed = urlparse(url)
    safe = parsed.netloc.replace(':', '_').replace('.', '_')
    safe = safe.replace('/', '_').replace('?', '_').replace('#', '_')
    safe = safe.replace('=', '_').replace('+', '_').replace('&', '_')
    return f"pack_cache/{safe}.json"

def load_from_url(url):
    cache_path = cache_filename(url)
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            return json.load(f)
    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()
        os.makedirs('pack_cache', exist_ok=True)
        with open(cache_path, 'w') as f:
            json.dump(data, f)
        return data
    except Exception as e:
        sys.stderr.write(f"Error fetching URL: {e}\n")
        sys.exit(1)

def load_from_file(path):
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception as e:
        sys.stderr.write(f"Error reading file: {e}\n")
        sys.exit(1)

def evaluate_expression(expr, vars_dict):
    try:
        return eval(expr, {'__builtins__': None}, vars_dict)
    except Exception as e:
        sys.stderr.write(f"Error evaluating expression: {e}\n")
        sys.exit(1)

def compute_values(pack):
    vars_dict = {}
    output_names = pack['output']

    for name, expr in pack['vars'].items():
        if name in output_names:
            continue
        try:
            vars_dict[name] = evaluate_expression(expr, vars_dict)
        except Exception as e:
            sys.stderr.write(f"Error computing {name}: {e}\n")
            sys.exit(1)

    for name in output_names:
        expr = pack['vars'][name]
        try:
            vars_dict[name] = evaluate_expression(expr, vars_dict)
        except Exception as e:
            sys.stderr.write(f"Error computing {name}: {e}\n")
            sys.exit(1)

    return vars_dict

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python runpack.py <pack_source> <output_path>\n")
        sys.exit(1)

    source = sys.argv[1]
    output_path = sys.argv[2]

    if source.startswith(('http://', 'https://')):
        pack = load_from_url(source)
    else:
        pack = load_from_file(source)

    if 'vars' not in pack or 'output' not in pack:
        sys.stderr.write("Invalid pack format: must contain 'vars' and 'output' keys\n")
        sys.exit(1)

    if not isinstance(pack['output'], list):
        sys.stderr.write("Invalid pack format: 'output' must be an array\n")
        sys.exit(1)

    values = compute_values(pack)

    with open(output_path, 'w') as f:
        json.dump(values, f, indent=2)

    os.chmod(output_path, 0o644)

if __name__ == "__main__":
    main()

import json
import os
import sys
import urllib.request
from urllib.error import URLError
from pathlib import Path

def sanitize_filename(url):
    sanitized = []
    for c in url:
        if c.isalnum() or c in ('-', '.', '_'):
            sanitized.append(c)
        else:
            sanitized.append('_')
    return ''.join(sanitized) + '.json'

def download_from_url(url):
    cache_dir = Path('./pack_cache')
    cache_dir.mkdir(exist_ok=True)
    cache_path = cache_dir / sanitize_filename(url)

    if cache_path.exists():
        return cache_path.read_text()

    try:
        with urllib.request.urlopen(url) as response:
            data = response.read().decode('utf-8')
        cache_path.write_text(data)
        return data
    except URLError as e:
        print(f"Error downloading from URL: {e.reason}", file=sys.stderr)
        sys.exit(1)

def evaluate_expression(expr, vars_dict):
    try:
        return eval(expr, {}, vars_dict)
    except Exception as e:
        print(f"Error evaluating expression '{expr}': {e}", file=sys.stderr)
        sys.exit(1)

def process_pack(pack_source):
    if pack_source.startswith(('http://', 'https://')):
        data = download_from_url(pack_source)
    else:
        try:
            with open(pack_source, 'r', encoding='utf-8') as f:
                data = f.read()
        except IOError as e:
            print(f"Error reading file: {e}", file=sys.stderr)
            sys.exit(1)

    try:
        pack = json.loads(data)
    except json.JSONDecodeError as e:
        print(f"Invalid JSON: {e}", file=sys.stderr)
        sys.exit(1)

    if 'vars' not in pack or 'output' not in pack:
        print("Invalid pack format: missing 'vars' or 'output'", file=sys.stderr)
        sys.exit(1)

    vars_dict = {}
    for name, expr in pack['vars'].items():
        if not isinstance(expr, str):
            print(f"Invalid expression type for '{name}': {type(expr)}", file=sys.stderr)
            sys.exit(1)
        vars_dict[name] = evaluate_expression(expr, vars_dict)

    output = pack['output']
    result = {}
    for name in output:
        if name not in vars_dict:
            print(f"Output name '{name}' not found in vars", file=sys.stderr)
            sys.exit(1)
        result[name] = vars_dict[name]

    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python runpack.py <pack_source> <output_path>", file=sys.stderr)
        sys.exit(1)

    pack_source = sys.argv[1]
    output_path = sys.argv[2]

    try:
        result = process_pack(pack_source)
        with open(output_path, 'w', encoding='utf-8') as f:
            json.dump(result, f, indent=2)
        print()  # Add trailing newline
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
